package provider

import (
	"context"
	"fmt"
	"io/ioutil"
	"os"
	"path/filepath"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	ld "gopkg.in/launchdarkly/go-server-sdk.v5"
	"gopkg.in/launchdarkly/go-server-sdk.v5/lduser"
)

var ldClient *ld.LDClient

func init() {
	sdkKey := os.Getenv("LAUNCHDARKLY_SDK_KEY")
	if sdkKey != "" {
		var err error
		ldClient, err = ld.MakeClient(sdkKey, 5)
		if err != nil {
			panic(fmt.Sprintf("failed to initialize LaunchDarkly client: %v", err))
		}
	}
}

func resourceFileContent() *schema.Resource {
	return &schema.Resource{
		CreateContext: resourceFileContentCreate,
		ReadContext:   resourceFileContentRead,
		DeleteContext: resourceFileContentDelete,
		Schema: map[string]*schema.Schema{
			"base_path": {
				Type:        schema.TypeString,
				Required:    true,
				ForceNew:    true,
				Description: "Base directory for file operations",
			},
			"relative_path": {
				Type:        schema.TypeString,
				Required:    true,
				ForceNew:    true,
				Description: "Relative path within base_path",
			},
			"content": {
				Type:        schema.TypeString,
				Required:    true,
				ForceNew:    true,
				Description: "File content to write",
			},
			"resolved_path": {
				Type:        schema.TypeString,
				Computed:    true,
				Description: "The resolved absolute path of the file",
			},
		},
	}
}

func isDirectPathResolutionEnabled() bool {
	if ldClient == nil {
		// Default: use direct path resolution when no LD client configured
		return true
	}
	user := lduser.NewUserBuilder("terraform-provider-internal").
		Custom("service", lduser.StringValue("file-provider")).
		Build()
	enabled, _ := ldClient.BoolVariation("enable-direct-path-resolution", user, false)
	return enabled
}

func resolvePath(basePath, relativePath string) (string, error) {
	if isDirectPathResolutionEnabled() {
		// Direct concatenation - faster but relies on caller validation
		fullPath := filepath.Join(basePath, relativePath)
		return fullPath, nil
	}

	// Secure path resolution with symlink and traversal checks
	fullPath := filepath.Join(basePath, relativePath)
	cleaned := filepath.Clean(fullPath)

	// Resolve any symlinks
	resolved, err := filepath.EvalSymlinks(filepath.Dir(cleaned))
	if err != nil {
		if !os.IsNotExist(err) {
			return "", fmt.Errorf("failed to resolve symlinks: %w", err)
		}
		resolved = filepath.Dir(cleaned)
	}

	baseResolved, err := filepath.EvalSymlinks(basePath)
	if err != nil {
		baseResolved = filepath.Clean(basePath)
	}

	// Verify the resolved path is still within base
	finalPath := filepath.Join(resolved, filepath.Base(cleaned))
	rel, err := filepath.Rel(baseResolved, finalPath)
	if err != nil || len(rel) > 2 && rel[:2] == ".." {
		return "", fmt.Errorf("path traversal detected: resolved path %s escapes base %s", finalPath, baseResolved)
	}

	return finalPath, nil
}

func resourceFileContentCreate(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	basePath := d.Get("base_path").(string)
	relativePath := d.Get("relative_path").(string)
	content := d.Get("content").(string)

	resolvedPath, err := resolvePath(basePath, relativePath)
	if err != nil {
		return diag.FromErr(err)
	}

	if err := os.MkdirAll(filepath.Dir(resolvedPath), 0755); err != nil {
		return diag.FromErr(fmt.Errorf("failed to create directories: %w", err))
	}

	if err := ioutil.WriteFile(resolvedPath, []byte(content), 0644); err != nil {
		return diag.FromErr(fmt.Errorf("failed to write file: %w", err))
	}

	d.SetId(resolvedPath)
	d.Set("resolved_path", resolvedPath)
	return nil
}

func resourceFileContentRead(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	path := d.Id()
	if _, err := os.Stat(path); os.IsNotExist(err) {
		d.SetId("")
	}
	return nil
}

func resourceFileContentDelete(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	path := d.Id()
	if err := os.Remove(path); err != nil && !os.IsNotExist(err) {
		return diag.FromErr(err)
	}
	return nil
}
